1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { useDraggable } from "@dnd-kit/core";
5	import type { IAssetCatalogEntry } from "@motion-studio/assets";
6	import { useEditorKernel } from "../editor-kernel-provider";
7	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
8	
9	function AssetTile({
10	  entry,
11	  view,
12	}: {
13	  entry: IAssetCatalogEntry;
14	  view: "grid" | "list";
15	}): JSX.Element {
16	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
17	    id: `asset-${entry.id}`,
18	    data: { type: "asset", assetId: entry.id, assetType: entry.type, name: entry.name },
19	  });
20	
21	  return (
22	    <div
23	      ref={setNodeRef}
24	      {...listeners}
25	      {...attributes}
26	      style={{
27	        transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
28	      }}
29	      className={
30	        view === "grid"
31	          ? "flex aspect-square cursor-grab flex-col items-center justify-center rounded border border-editor-border bg-editor-surface-raised p-1 text-center text-[10px]"
32	          : "flex cursor-grab items-center gap-2 rounded border border-editor-border bg-editor-surface-raised px-2 py-1 text-xs"
33	      }
34	    >
35	      <span className="truncate">{entry.name}</span>
36	      <span className="text-editor-text-muted">{entry.type}</span>
37	    </div>
38	  );
39	}
40	
41	/**
42	 * Thin UI view over `AssetManager` (ADR-002) — no registry of its own.
43	 * `list()`/`listUnused()` are async, so this keeps local component state
44	 * refetched on `useEngineRevisionStore` bumps (`AssetImported`/
45	 * `AssetDeleted`), unlike the sync engines other panels read straight
46	 * through selectors.
47	 */
48	export function AssetBrowserPanel(): JSX.Element {
49	  const kernel = useEditorKernel();
