30	        {muted ? "Muted" : ""} {locked ? "Locked" : ""}
31	      </span>
32	    </div>
33	  );
34	}
35	
36	function ClipBar({
37	  kernel,
38	  trackItemId,
39	  layerId,
40	  left,
41	  width,
42	  selected,
43	}: {
44	  kernel: EditorKernel;
45	  trackItemId: TrackItemId;
46	  layerId: LayerId;
47	  left: number;
48	  width: number;
49	  selected: boolean;
50	}): JSX.Element {
51	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
52	    id: `clip-${trackItemId}`,
53	    data: { type: "clip", trackItemId },
54	  });
55	  const layer = kernel.layerEngine.registry.get(layerId);
56	  const select = useTimelineStore((state) => state.select);
57	
58	  const handleClick = (event: MouseEvent): void => {
59	    event.stopPropagation();
60	    select({ layerIds: layer ? [layer.id] : [], trackItemIds: [trackItemId] });
61	  };
62	
63	  return (
64	    <button
65	      ref={setNodeRef}
66	      {...listeners}
67	      {...attributes}
68	      type="button"
69	      onClick={handleClick}
70	      className={`absolute top-1 flex h-14 items-center overflow-hidden rounded border px-2 text-left text-xs ${
71	        selected
72	          ? "border-editor-accent bg-editor-accent/40"
73	          : "border-editor-border bg-editor-surface-raised"
74	      }`}
75	      style={{
76	        left,
77	        width: Math.max(width, 4),
78	        transform: transform ? `translate3d(${transform.x}px, 0, 0)` : undefined,
79	      }}
80	    >
81	      {layer?.name ?? "Clip"}
82	    </button>
83	  );
84	}
85	
86	function TrackLane({
87	  kernel,
88	  trackId,
89	  ticksPerPixel,
90	  onScrub,
91	}: {
92	  kernel: EditorKernel;
93	  trackId: TrackId;
94	  ticksPerPixel: number;
95	  onScrub: (tick: Tick) => void;
96	}): JSX.Element {
97	  const { setNodeRef } = useDroppable({ id: `track-${trackId}`, data: { type: "track", trackId } });
98	  const selection = useTimelineStore((state) => state.selection);
99	  const items = kernel.timelineEngine.getTrackItemsSorted(trackId);
100	
101	  const handleBackgroundClick = (event: MouseEvent<HTMLDivElement>): void => {
102	    const rect = event.currentTarget.getBoundingClientRect();
103	    onScrub(toTick((event.clientX - rect.left) * ticksPerPixel));
104	  };
105	
106	  return (
107	    <div
108	      ref={setNodeRef}
109	      onClick={handleBackgroundClick}
110	      className="relative h-16 shrink-0 border-b border-editor-border"
111	    >
112	      {items.map((item) => (
113	        <ClipBar
114	          key={item.id}
115	          kernel={kernel}
116	          trackItemId={item.id}
