  await page.mouse.move(sourceBox.x + 10, sourceBox.y + 10, { steps: 5 });
  await page.mouse.move(targetBox.x + targetOffsetX, targetBox.y + targetBox.height / 2, {
    steps: 10,
  });
  await page.mouse.up();
