  locked,
}: {
  label: string;
  muted: boolean;
  locked: boolean;
}): JSX.Element {
  return (
    <div className="flex h-16 shrink-0 flex-col justify-center gap-0.5 border-b border-r border-editor-border bg-editor-surface px-2 text-xs">
