  // already in play elsewhere in the tree; this local subscription just
  // keeps the playhead position live while this panel is mounted.
  useEffect(() => kernel.playback.onTick(() => undefined), [kernel]);

  const composition = kernel.timelineEngine.requireComposition(kernel.defaultCompositionId);

