        >
          {isPlaying ? (
            <Pause className="h-4 w-4" aria-hidden />
          ) : (
            <Play className="h-4 w-4" aria-hidden />
          )}
        </button>
        <span className="tabular-nums">
          {formatTimecode(currentTick, composition.fps)} |{" "}
          {formatTimecode(composition.durationTicks, composition.fps)}
        </span>
      </div>

      <div className="flex items-center gap-2">
        <ZoomOut
          className="h-4 w-4 cursor-pointer"
          aria-hidden
          onClick={() =>
            setZoom(Math.min(MAX_ZOOM_TICKS_PER_PIXEL, zoomTicksPerPixel + ZOOM_STEP))
          }
        />
        <input
          type="range"
          min={MIN_ZOOM_TICKS_PER_PIXEL}
          max={MAX_ZOOM_TICKS_PER_PIXEL}
          value={zoomTicksPerPixel}
          onChange={(event) => setZoom(Number(event.target.value))}
          className="w-24"
        />
        <ZoomIn
          className="h-4 w-4 cursor-pointer"
          aria-hidden
          onClick={() =>
            setZoom(Math.max(MIN_ZOOM_TICKS_PER_PIXEL, zoomTicksPerPixel - ZOOM_STEP))
          }
        />
        <button
          type="button"
          onClick={handleDelete}
          title="Delete selection"
          className="rounded p-1 hover:bg-editor-surface-raised"
        >
          <Trash2 className="h-4 w-4" aria-hidden />
        </button>
      </div>
    </div>
  );
}

