}: {
  trackAreaRef: RefObject<HTMLDivElement>;
  currentTick: Tick;
  zoomTicksPerPixel: number;
  onSeek: (tick: Tick) => void;
}): JSX.Element {
  const seekFromClientX = (clientX: number): void => {
    const rect = trackAreaRef.current?.getBoundingClientRect();
    if (!rect) {
      return;
