import { useEffect, useRef, useState } from "react";
import { useDraggable } from "@dnd-kit/core";
import { FileAudio, Plus, Search } from "lucide-react";
import type { IAssetCatalogEntry } from "@motion-studio/assets";
import { AssetType } from "@motion-studio/shared";
import { useEditorKernel } from "../editor-kernel-provider";
import { useEngineRevisionStore } from "../../state/use-engine-revision-store";

/** Object URL for an Image/Video asset's raw bytes, `undefined` while loading/unavailable. Revoked on unmount/entry change. */
function useAssetPreviewUrl(entry: IAssetCatalogEntry): string | undefined {
  const kernel = useEditorKernel();
  const [url, setUrl] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (entry.type !== AssetType.Image && entry.type !== AssetType.Video) {
      return;
    }
    let objectUrl: string | undefined;
    let cancelled = false;
    kernel.assetEditor.getBlob(entry.id).then((data) => {
      if (cancelled || !data) {
        return;
      }
      objectUrl = URL.createObjectURL(new Blob([data], { type: entry.mimeType }));
      setUrl(objectUrl);
    });
    return () => {
      cancelled = true;
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
      }
    };
  }, [kernel, entry.id, entry.type, entry.mimeType]);

  return url;
}

function AssetPreview({ entry }: { entry: IAssetCatalogEntry }): JSX.Element {
  const url = useAssetPreviewUrl(entry);

  if (entry.type === AssetType.Image) {
    return url ? (
      // eslint-disable-next-line @next/next/no-img-element -- local blob URL, not a next/image-optimizable remote asset
      <img src={url} alt="" className="h-full w-full rounded object-cover" />
    ) : (
      <div className="h-full w-full animate-pulse rounded bg-editor-surface" />
