27	const TRACK_ICON: Partial<Record<TrackType, LucideIcon>> = {
28	  [TrackType.Video]: Film,
29	  [TrackType.Audio]: Music2,
30	  [TrackType.Text]: Type,
31	  [TrackType.Sticker]: Sticker,
32	  [TrackType.Effect]: Wand2,
33	};
