35	const CHIP_STYLE: Partial<Record<TrackType, string>> = {
36	  [TrackType.Video]: "bg-chip-video-bg text-chip-video-text",
37	  [TrackType.Audio]: "bg-chip-audio-bg text-chip-audio-text",
38	  [TrackType.Text]: "bg-chip-text-bg text-chip-text-text",
39	  [TrackType.Effect]: "bg-chip-effect-bg text-chip-effect-text",
40	};
41	const DEFAULT_CHIP_STYLE = "bg-chip-default-bg text-chip-default-text";
42	
43	const NICE_SECOND_INTERVALS = [1, 2, 5, 10, 15, 30, 60, 120, 300, 600];
44	const LARGEST_RULER_INTERVAL_SECONDS = NICE_SECOND_INTERVALS[NICE_SECOND_INTERVALS.length - 1] ?? 600;
45	const MIN_RULER_MARK_SPACING_PX = 80;
46	
47	function pad(value: number): string {
48	  return value.toString().padStart(2, "0");
49	}
50	
51	function formatRulerLabel(totalSeconds: number): string {
52	  const minutes = Math.floor(totalSeconds / 60);
53	  const seconds = Math.floor(totalSeconds % 60);
54	  return `${pad(minutes)}:${pad(seconds)}`;
55	}
56	
57	function pickRulerIntervalSeconds(zoomTicksPerPixel: number, fps: number): number {
58	  const perSecond = ticksPerSecond(fps);
59	  return (
60	    NICE_SECOND_INTERVALS.find(
61	      (seconds) => (seconds * perSecond) / zoomTicksPerPixel >= MIN_RULER_MARK_SPACING_PX,
62	    ) ?? LARGEST_RULER_INTERVAL_SECONDS
63	  );
64	}
65	
66	function TimelineRuler({
67	  durationTicks,
68	  zoomTicksPerPixel,
69	  fps,
70	}: {
71	  durationTicks: Tick;
72	  zoomTicksPerPixel: number;
73	  fps: number;
74	}): JSX.Element {
75	  const intervalSeconds = pickRulerIntervalSeconds(zoomTicksPerPixel, fps);
76	  const perSecond = ticksPerSecond(fps);
77	  const intervalTicks = intervalSeconds * perSecond;
78	  const marks: number[] = [];
79	  for (let tick = 0; tick <= durationTicks; tick += intervalTicks) {
80	    marks.push(tick);
81	  }
82	
83	  return (
84	    <div className="relative h-6 shrink-0 border-b border-editor-border text-[10px] text-editor-text-muted">
