86	        <span
87	          key={tick}
88	          className="absolute top-1"
89	          style={{ left: tick / zoomTicksPerPixel }}
90	        >
91	          {formatRulerLabel(tick / perSecond)}
92	        </span>
93	      ))}
94	    </div>
95	  );
96	}
