103	    <div className="flex h-16 w-10 shrink-0 flex-col items-center justify-center gap-1 border-b border-r border-editor-border bg-editor-surface">
104	      <Icon className="h-3.5 w-3.5 text-editor-text-muted" aria-hidden />
105	      <MuteIcon
106	        className="h-3.5 w-3.5 text-editor-text-muted"
107	        aria-label={muted ? "Muted" : "Unmuted"}
108	      />
109	    </div>
110	  );
111	}
112	
113	function ClipBar({
114	  kernel,
115	  trackItemId,
116	  layerId,
117	  trackType,
118	  left,
119	  width,
120	  selected,
121	}: {
122	  kernel: EditorKernel;
123	  trackItemId: TrackItemId;
124	  layerId: LayerId;
125	  trackType: TrackType;
126	  left: number;
127	  width: number;
128	  selected: boolean;
129	}): JSX.Element {
130	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
131	    id: `clip-${trackItemId}`,
132	    data: { type: "clip", trackItemId },
133	  });
134	  const layer = kernel.layerEngine.registry.get(layerId);
135	  const select = useTimelineStore((state) => state.select);
136	  const Icon = TRACK_ICON[trackType] ?? Film;
137	
138	  const handleClick = (event: MouseEvent): void => {
139	    event.stopPropagation();
140	    select({ layerIds: layer ? [layer.id] : [], trackItemIds: [trackItemId] });
141	  };
142	
143	  return (
144	    <button
145	      ref={setNodeRef}
146	      {...listeners}
147	      {...attributes}
148	      type="button"
149	      onClick={handleClick}
150	      className={`absolute top-1 flex h-14 items-center gap-1 overflow-hidden rounded-lg px-2 text-left text-xs ${
151	        CHIP_STYLE[trackType] ?? DEFAULT_CHIP_STYLE
152	      } ${selected ? "ring-2 ring-editor-accent" : ""}`}
153	      style={{
154	        left,
155	        width: Math.max(width, 4),
156	        transform: transform ? `translate3d(${transform.x}px, 0, 0)` : undefined,
157	      }}
158	    >
159	      <Icon className="h-3 w-3 shrink-0 opacity-70" aria-hidden />
160	      {layer?.name ?? "Clip"}
161	    </button>
162	  );
163	}
164	
165	function TrackLane({
166	  kernel,
167	  trackId,
168	  trackType,
169	  ticksPerPixel,
170	  onScrub,
171	}: {
172	  kernel: EditorKernel;
173	  trackId: TrackId;
