235	    if (!event.currentTarget.hasPointerCapture(event.pointerId)) {
236	      return;
237	    }
238	    seekFromClientX(event.clientX);
239	  };
240	
241	  return (
242	    <div
243	      onPointerDown={handlePointerDown}
244	      onPointerMove={handlePointerMove}
245	      className="absolute inset-y-0 z-10 w-3 -translate-x-1/2 cursor-ew-resize"
246	      style={{ left: currentTick / zoomTicksPerPixel }}
