3	import { useEffect, useRef, useState } from "react";
4	import { useDraggable } from "@dnd-kit/core";
5	import { FileAudio, Plus, Search } from "lucide-react";
6	import type { IAssetCatalogEntry } from "@motion-studio/assets";
7	import { AssetType } from "@motion-studio/shared";
8	import { useEditorKernel } from "../editor-kernel-provider";
9	import { useEngineRevisionStore } from "../../state/use-engine-revision-store";
10	
11	/** Object URL for an Image/Video asset's raw bytes, `undefined` while loading/unavailable. Revoked on unmount/entry change. */
12	function useAssetPreviewUrl(entry: IAssetCatalogEntry): string | undefined {
13	  const kernel = useEditorKernel();
14	  const [url, setUrl] = useState<string | undefined>(undefined);
15	
16	  useEffect(() => {
17	    if (entry.type !== AssetType.Image && entry.type !== AssetType.Video) {
18	      return;
19	    }
20	    let objectUrl: string | undefined;
21	    let cancelled = false;
22	    kernel.assetEditor.getBlob(entry.id).then((data) => {
23	      if (cancelled || !data) {
24	        return;
25	      }
26	      objectUrl = URL.createObjectURL(
27	        new Blob([data as unknown as BlobPart], { type: entry.mimeType }),
28	      );
29	      setUrl(objectUrl);
30	    });
31	    return () => {
32	      cancelled = true;
33	      if (objectUrl) {
34	        URL.revokeObjectURL(objectUrl);
35	      }
36	    };
37	  }, [kernel, entry.id, entry.type, entry.mimeType]);
38	
39	  return url;
40	}
41	
42	function AssetPreview({ entry }: { entry: IAssetCatalogEntry }): JSX.Element {
43	  const url = useAssetPreviewUrl(entry);
44	
45	  if (entry.type === AssetType.Image) {
46	    return url ? (
47	      <img
48	        src={url}
49	        alt=""
50	        draggable={false}
51	        className="pointer-events-none h-full w-full rounded object-cover"
52	      />
53	    ) : (
54	      <div className="h-full w-full animate-pulse rounded bg-editor-surface" />
55	    );
56	  }
57	
58	  if (entry.type === AssetType.Video) {
59	    return url ? (
60	      <video
61	        src={url}
62	        muted
63	        preload="metadata"
64	        draggable={false}
65	        className="pointer-events-none h-full w-full rounded object-cover"
66	      />
67	    ) : (
68	      <div className="h-full w-full animate-pulse rounded bg-editor-surface" />
69	    );
70	  }
71	
72	  return (
73	    <div className="flex h-full w-full items-center justify-center rounded bg-editor-surface">
74	      <FileAudio className="h-5 w-5 text-editor-text-muted" aria-hidden />
75	    </div>
76	  );
77	}
78	
79	function AssetTile({
80	  entry,
81	  view,
82	}: {
83	  entry: IAssetCatalogEntry;
84	  view: "grid" | "list";
85	}): JSX.Element {
86	  const { attributes, listeners, setNodeRef, transform } = useDraggable({
87	    id: `asset-${entry.id}`,
88	    data: { type: "asset", assetId: entry.id, assetType: entry.type, name: entry.name },
89	  });
90	
91	  if (view === "list") {
92	    return (
93	      <div
94	        ref={setNodeRef}
95	        {...listeners}
96	        {...attributes}
97	        style={{
98	          transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
99	        }}
100	        className="flex min-w-0 cursor-grab items-center gap-2 rounded-lg border border-editor-border bg-editor-surface-raised px-2 py-1 text-xs"
101	      >
102	        <span className="min-w-0 flex-1 truncate">{entry.name}</span>
103	        <span className="shrink-0 text-editor-text-muted">{entry.type}</span>
104	      </div>
105	    );
106	  }
107	
108	  return (
109	    <div
110	      ref={setNodeRef}
111	      {...listeners}
112	      {...attributes}
113	      style={{
114	        transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
115	      }}
116	      className="flex min-w-0 cursor-grab flex-col gap-1 rounded-lg border border-editor-border bg-editor-surface-raised p-1"
117	    >
118	      <div className="aspect-square w-full overflow-hidden">
119	        <AssetPreview entry={entry} />
120	      </div>
121	      <div className="min-w-0 text-center text-[10px]">
122	        <div className="w-full truncate">{entry.name}</div>
123	        <div className="w-full truncate text-editor-text-muted">{entry.type}</div>
124	      </div>
125	    </div>
126	  );
127	}
128	
129	/**
