"use client";

import { useEffect, useRef, useState } from "react";
import { useDraggable } from "@dnd-kit/core";
import { FileAudio, Plus, Search } from "lucide-react";
import type { IAssetCatalogEntry } from "@motion-studio/assets";
import { AssetType } from "@motion-studio/shared";
import { useEditorKernel } from "../editor-kernel-provider";
import { useEngineRevisionStore } from "../../state/use-engine-revision-store";

/** Object URL for an Image/Video asset's raw bytes, `undefined` while loading/unavailable. Revoked on unmount/entry change. */
function useAssetPreviewUrl(entry: IAssetCatalogEntry): string | undefined {
  const kernel = useEditorKernel();
  const [url, setUrl] = useState<string | undefined>(undefined);

  useEffect(() => {
    if (entry.type !== AssetType.Image && entry.type !== AssetType.Video) {
      return;
    }
    let objectUrl: string | undefined;
    let cancelled = false;
    kernel.assetEditor.getBlob(entry.id).then((data) => {
      if (cancelled || !data) {
        return;
      }
      objectUrl = URL.createObjectURL(
        new Blob([data as unknown as BlobPart], { type: entry.mimeType }),
      );
      setUrl(objectUrl);
    });
    return () => {
      cancelled = true;
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
      }
    };
  }, [kernel, entry.id, entry.type, entry.mimeType]);

  return url;
}

function AssetPreview({ entry }: { entry: IAssetCatalogEntry }): JSX.Element {
  const url = useAssetPreviewUrl(entry);

  if (entry.type === AssetType.Image) {
    return url ? (
      <img
        src={url}
        alt=""
        draggable={false}
        className="pointer-events-none h-full w-full rounded object-cover"
      />
    ) : (
      <div className="h-full w-full animate-pulse rounded bg-editor-surface" />
    );
  }

  if (entry.type === AssetType.Video) {
    return url ? (
      <video
        src={url}
        muted
        preload="metadata"
        draggable={false}
        className="pointer-events-none h-full w-full rounded object-cover"
      />
    ) : (
      <div className="h-full w-full animate-pulse rounded bg-editor-surface" />
    );
  }

  return (
    <div className="flex h-full w-full items-center justify-center rounded bg-editor-surface">
      <FileAudio className="h-5 w-5 text-editor-text-muted" aria-hidden />
    </div>
  );
}

function AssetTile({
  entry,
  view,
}: {
  entry: IAssetCatalogEntry;
  view: "grid" | "list";
}): JSX.Element {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({
    id: `asset-${entry.id}`,
    data: { type: "asset", assetId: entry.id, assetType: entry.type, name: entry.name },
  });

  if (view === "list") {
    return (
      <div
        ref={setNodeRef}
        {...listeners}
        {...attributes}
        style={{
          transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
        }}
        className="flex min-w-0 cursor-grab items-center gap-2 rounded-lg border border-editor-border bg-editor-surface-raised px-2 py-1 text-xs"
      >
        <span className="min-w-0 flex-1 truncate">{entry.name}</span>
        <span className="shrink-0 text-editor-text-muted">{entry.type}</span>
      </div>
    );
  }

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      style={{
        transform: transform ? `translate3d(${transform.x}px, ${transform.y}px, 0)` : undefined,
      }}
      className="flex min-w-0 cursor-grab flex-col gap-1 rounded-lg border border-editor-border bg-editor-surface-raised p-1"
    >
      <div className="aspect-square w-full overflow-hidden">
        <AssetPreview entry={entry} />
      </div>
      <div className="min-w-0 text-center text-[10px]">
        <div className="w-full truncate">{entry.name}</div>
        <div className="w-full truncate text-editor-text-muted">{entry.type}</div>
      </div>
    </div>
  );
}

/**
 * Thin UI view over `AssetManager` (ADR-002) — no registry of its own.
 * `list()`/`listUnused()` are async, so this keeps local component state
 * refetched on `useEngineRevisionStore` bumps (`AssetImported`/
 * `AssetDeleted`), unlike the sync engines other panels read straight
 * through selectors.
 */
export function AssetBrowserPanel({ assetType }: { assetType?: AssetType }): JSX.Element {
  const kernel = useEditorKernel();
  const revision = useEngineRevisionStore((state) => state.revision);
  const [entries, setEntries] = useState<IAssetCatalogEntry[]>([]);
  const [view, setView] = useState<"grid" | "list">("grid");
  const [search, setSearch] = useState("");
  const [unusedOnly, setUnusedOnly] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let cancelled = false;
    const load = unusedOnly ? kernel.assetEditor.listUnused() : kernel.assetEditor.list();
    load.then((result) => {
      if (!cancelled) {
        setEntries(result);
      }
    });
    return () => {
      cancelled = true;
    };
  }, [kernel, revision, unusedOnly]);

  const filtered = entries
    .filter((entry) => !assetType || entry.type === assetType)
    .filter((entry) => entry.name.toLowerCase().includes(search.toLowerCase()));

  const handleImport = async (files: FileList | null): Promise<void> => {
    if (!files) {
      return;
    }
    for (const file of Array.from(files)) {
      const data = new Uint8Array(await file.arrayBuffer());
      try {
        await kernel.assetEditor.import({ fileName: file.name, mimeType: file.type, data });
      } catch (error) {
        console.error(`AssetBrowserPanel: failed to import "${file.name}"`, error);
      }
    }
  };

  return (
    <div className="flex h-full flex-col gap-3 overflow-y-auto p-3 text-xs">
      <div className="flex items-center gap-2 rounded-lg border border-editor-border bg-editor-bg px-2 py-1.5">
        <Search className="h-3.5 w-3.5 text-editor-text-muted" aria-hidden />
        <input
          type="text"
          placeholder="Search assets…"
          value={search}
          onChange={(event) => setSearch(event.target.value)}
          className="w-full bg-transparent text-editor-text placeholder:text-editor-text-muted focus:outline-none"
        />
        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          title="Import"
          className="shrink-0 rounded p-1 text-editor-text-muted hover:bg-editor-surface-raised"
        >
          <Plus className="h-3.5 w-3.5" aria-hidden />
        </button>
        <input
          ref={fileInputRef}
          type="file"
          multiple
          className="hidden"
          onChange={(event) => {
            void handleImport(event.target.files);
            event.target.value = "";
          }}
        />
      </div>

      <div className="flex items-center gap-2 text-editor-text-muted">
        <label className="flex items-center gap-1">
          <input
            type="checkbox"
            checked={unusedOnly}
            onChange={(event) => setUnusedOnly(event.target.checked)}
          />
          Unused only
        </label>
        <button
          type="button"
          onClick={() => setView(view === "grid" ? "list" : "grid")}
          className="ml-auto rounded px-2 py-1 hover:bg-editor-surface-raised"
        >
          {view === "grid" ? "List" : "Grid"}
        </button>
      </div>

      <div className={view === "grid" ? "grid grid-cols-2 gap-2" : "flex flex-col gap-1"}>
        {filtered.map((entry) => (
          <AssetTile key={entry.id} entry={entry} view={view} />
        ))}
        {filtered.length === 0 && <span className="text-editor-text-muted">No assets</span>}
      </div>
    </div>
  );
}

